import random
# For a Man-in-the-Middle (MITM) attack, we will use Eve as the attacker
# Public parameter : g is a generator of G, a subgroup of order q
# To generate the group G, according to the NIST SP 800-56A Rev. 3 standard, i have to use a safe-prime group

# Function that converts hexadecimal numbers to decimal numbers
def conv_htd(n):
    n = int(n, 16)
    return n

# The hexadecimal representation of p is 
# The hexadecimal representation of q is 
p = conv_htd("")
q = (p-1)//2
# The generator of the group is g = 2
g = 2

# Alice picks a random number nA in [1,p-1]
nA = random.randint(2,p-2)
# Alice computes g^{nA} in G
g_nA = pow(g,nA,p)
# Alice sends it to Bob, but Eve intercepts the message
# Eve gets g^{nA} instead of Bob

# Eve picks a random number nE in [1,p-1]
nE = random.randint(2,p-2)
# Eve computes g^{nE} in G
g_nE = pow(g,nE,p)
# Eve sends it to Alice
# Alice reçoit g^{nE}

# Alice and Eve share a common secret key g^{nA*nE} = g^{nE*nA}
skAE = pow(g_nE,nA,p)
skEA = pow(g_nA,nE,p)
if skAE == skEA:
    print(True)
else:
    print(False)

# Bob picks a random number nB in [1,p-1]
nB = random.randint(2,p-2)
# Bob computes g^{nB} in G
g_nB = pow(g,nB,p)
# Bob sent g_nB to Alice but Eve intercepts the message
# Eve gets g^{nB} instead of Alice

# Bob and Eve share a common secret key g^{nB*nE} = g^{nE*nB}
skBE = pow(g_nE,nB,p)
skEB = pow(g_nB,nE,p)
if skBE == skEB:
    print(True)
else:
    print(False)

if skAE == skEA and skBE == skEB:
    print("Eve established separate shared secrets with Alice and Bob, and the man-in-the-middle attack has succeeded.")
else:
    print("Fail, retry ;)")